import React, { useState } from 'react';
import { Line } from 'react-chartjs-2';
import { Chart as ChartJS, CategoryScale, LinearScale, PointElement, LineElement, Title, Tooltip, Legend } from 'chart.js';
import ManageTeachers from './ManageTeachers';
import TeachersList from './TeachersList';

ChartJS.register(CategoryScale, LinearScale, PointElement, LineElement, Title, Tooltip, Legend);

export default function LmsDashboard({ handleLogout }) {
  const [currentSubPage, setCurrentSubPage] = useState('Overview');

  const menuItems = [
    { name: 'Overview', icon: '📊' },
    { name: 'Students', icon: '👨‍🎓' },
    { name: 'Teachers & Classes', icon: '🏫' },
    { name: 'Reports', icon: '📋' },
    { name: 'Settings', icon: '⚙️' }
  ];

  // Stats Data
  const stats = { totalStudents: '1,250', totalTeachers: '45', activeClasses: '120', inactiveStudents: '25' };

  // Growth Chart Data
  const growthData = {
    labels: ['Jan', 'Feb', 'Mar', 'Apr', 'May'],
    datasets: [{
      label: 'Enrollment Growth',
      data: [10, 32, 25, 48, 80],
      borderColor: '#15803d',
      backgroundColor: 'rgba(21, 128, 61, 0.1)',
      tension: 0.4,
      fill: true
    }]
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', minHeight: '100vh', width: '100vw', backgroundColor: '#f8fafc', fontFamily: 'sans-serif' }}>
      
      {/* 1. Header (Welcome & Logout) */}
      <div style={{ 
        display: 'flex', justifyContent: 'space-between', alignItems: 'center', 
        padding: '15px 40px', backgroundColor: '#ffffff', borderBottom: '1px solid #e2e8f0' 
      }}>
        <span style={{ fontWeight: '700', color: '#1e293b' }}>Welcome, admin 👋</span>
        <button onClick={handleLogout} style={{ backgroundColor: '#dc2626', color: '#ffffff', border: 'none', padding: '8px 16px', borderRadius: '6px', cursor: 'pointer', fontWeight: 'bold' }}>
          Logout
        </button>
      </div>

      {/* 2. Middle Section */}
      <div style={{ display: 'flex', flex: 1 }}>
        
        {/* Sidebar */}
        <div style={{ width: '260px', backgroundColor: '#15803d', color: '#ffffff', padding: '25px 0' }}>
          <h2 style={{ fontSize: '20px', fontWeight: 'bold', padding: '0 25px', marginBottom: '25px' }}>Admin Panel</h2>
          <nav style={{ display: 'flex', flexDirection: 'column', gap: '8px', padding: '0 15px' }}>
            {menuItems.map((item) => (
              <button key={item.name} onClick={() => setCurrentSubPage(item.name)} style={{
                display: 'flex', alignItems: 'center', gap: '14px', width: '100%', padding: '12px 15px',
                backgroundColor: currentSubPage === item.name ? 'rgba(0,0,0,0.2)' : 'transparent',
                color: '#ffffff', border: 'none', borderRadius: '8px', cursor: 'pointer', textAlign: 'left'
              }}>
                {item.icon} {item.name}
              </button>
            ))}
          </nav>
        </div>

        {/* 3. Right Main Content */}
        <div style={{ flex: 1, padding: '40px' }}>
          
          {currentSubPage === 'Overview' && (
            <div style={{ display: 'flex', flexDirection: 'column', gap: '30px' }}>
              {/* Stats Cards */}
              <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: '25px' }}>
                {[ {t: 'Total Students', v: stats.totalStudents, i: '👨‍🎓'}, {t: 'Total Teachers', v: stats.totalTeachers, i: '👩‍🏫'}, {t: 'Active Classes', v: stats.activeClasses, i: '🏫'}, {t: 'Inactive', v: stats.inactiveStudents, i: '⚠️'} ].map((card, i) => (
                  <div key={i} style={{ background: '#ffffff', padding: '20px', borderRadius: '12px', border: '1px solid #e2e8f0' }}>
                    <p style={{ color: '#64748b', fontSize: '12px' }}>{card.t}</p>
                    <h2 style={{ margin: '5px 0 0 0' }}>{card.v}</h2>
                  </div>
                ))}
              </div>
              
              {/* Chart */}
              <div style={{ background: '#ffffff', padding: '25px', borderRadius: '12px', border: '1px solid #e2e8f0', height: '300px' }}>
                <Line data={growthData} options={{ responsive: true, maintainAspectRatio: false }} />
              </div>
            </div>
          )}

          {currentSubPage === 'Teachers & Classes' && (
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: '15px' }}>
              <button onClick={() => setCurrentSubPage('Manage Teachers')} style={{ padding: '20px' }}>Manage Teachers</button>
              <button onClick={() => setCurrentSubPage('Add New Teacher')} style={{ padding: '20px' }}>Add New Teacher</button>
              <button style={{ padding: '20px' }}>Create Class</button>
              <button style={{ padding: '20px' }}>Manage Courses</button>
            </div>
          )}

          {/* Load Subpages */}
          {currentSubPage === 'Manage Teachers' && <ManageTeachers />}
          {currentSubPage === 'Add New Teacher' && <ManageTeachers />}
          {currentSubPage === 'Students' && <div><h2>👨‍🎓 Student Management</h2></div>}
          {currentSubPage === 'Reports' && <div><h2>📋 Reports Section</h2></div>}
          {currentSubPage === 'Settings' && <div><h2>⚙️ Settings Section</h2></div>}
        </div>
      </div>
    </div>
  );
}
